/**
 * The Daemon is an LLM persona conditioned on the relic produced by an
`innoculation` job (Spectral + Speculative outputs). Stateless: clients
send the full message history every call; nothing is persisted server-side.

 * @summary Send a chat turn to the relic's Daemon
 */
export const getChatWithDaemonUrl = (id: string) => {
  return `/api/jobs/${id}/daemon/messages`;
};

export const chatWithDaemon = async (
  id: string,
  daemonChatRequest: DaemonChatRequest,
  options?: RequestInit,
): Promise<DaemonChatResponse> => {
  return customFetch<DaemonChatResponse>(getChatWithDaemonUrl(id), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(daemonChatRequest),
  });
};

export const getChatWithDaemonMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof chatWithDaemon>>,
    TError,
    { id: string; data: BodyType<DaemonChatRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof chatWithDaemon>>,
  TError,
  { id: string; data: BodyType<DaemonChatRequest> },
  TContext
> => {
  const mutationKey = ["chatWithDaemon"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof chatWithDaemon>>,
    { id: string; data: BodyType<DaemonChatRequest> }
  > = (props) => {
    const { id, data } = props ?? {};

    return chatWithDaemon(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type ChatWithDaemonMutationResult = NonNullable<
  Awaited<ReturnType<typeof chatWithDaemon>>
>;
export type ChatWithDaemonMutationBody = BodyType<DaemonChatRequest>;
export type ChatWithDaemonMutationError = ErrorType<ErrorResponse>;

/**
 * @summary Send a chat turn to the relic's Daemon
 */
export const useChatWithDaemon = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof chatWithDaemon>>,
    TError,
    { id: string; data: BodyType<DaemonChatRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof chatWithDaemon>>,
  TError,
  { id: string; data: BodyType<DaemonChatRequest> },
  TContext
> => {
  return useMutation(getChatWithDaemonMutationOptions(options));
};

/**
 * Returns counts of jobs grouped by status and kind, plus recent verdict breakdown. Useful for dashboards. When `kind` is supplied, `total`, `by_status`, `by_verdict`, and `recent_24h` are scoped to that kind; `by_kind` always reports global counts.
 * @summary Job stats summary
 */
export const getGetJobStatsUrl = (params?: GetJobStatsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/jobs/stats?${stringifiedParams}`
    : `/api/jobs/stats`;
};

export const getJobStats = async (
  params?: GetJobStatsParams,
  options?: RequestInit,
): Promise<JobStats> => {
  return customFetch<JobStats>(getGetJobStatsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetJobStatsQueryKey = (params?: GetJobStatsParams) => {
  return [`/api/jobs/stats`, ...(params ? [params] : [])] as const;
};

export const getGetJobStatsQueryOptions = <
  TData = Awaited<ReturnType<typeof getJobStats>>,
  TError = ErrorType<unknown>,
>(
  params?: GetJobStatsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getJobStats>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetJobStatsQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getJobStats>>> = ({
    signal,
  }) => getJobStats(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getJobStats>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetJobStatsQueryResult = NonNullable<
  Awaited<ReturnType<typeof getJobStats>>
>;
export type GetJobStatsQueryError = ErrorType<unknown>;

/**
 * @summary Job stats summary
 */

export function useGetJobStats<
  TData = Awaited<ReturnType<typeof getJobStats>>,
  TError = ErrorType<unknown>,
>(
  params?: GetJobStatsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getJobStats>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetJobStatsQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
